package pi

import (
	"bufio"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"os/exec"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/review"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// NewReviewer returns the AgentReviewer for Pi.
//
// Argv shape: pi --mode json --print [--model <model>] <prompt>.
// The prompt is passed as a positional message because Pi's CLI accepts prompts
// as message arguments in non-interactive mode. Stdout is newline-delimited JSON
// session events; the parser maps Pi's AgentSessionEvent stream into Entire's
// review Event stream.
func NewReviewer() *reviewtypes.ReviewerTemplate {
	return &reviewtypes.ReviewerTemplate{
		AgentName: string(agent.AgentNamePi),
		BuildCmd:  buildPiReviewCmd,
		Parser:    parsePiReviewOutput,
	}
}

func buildPiReviewCmd(ctx context.Context, cfg reviewtypes.RunConfig) *exec.Cmd {
	prompt := review.ComposeReviewPrompt(cfg)
	args := []string{"--mode", "json", "--print"}
	if cfg.Model != "" {
		args = append(args, "--model", cfg.Model)
	}
	args = append(args, prompt)
	cmd := exec.CommandContext(ctx, "pi", args...)
	cmd.Env = review.AppendReviewEnv(os.Environ(), string(agent.AgentNamePi), cfg, prompt)
	return cmd
}

func parsePiReviewOutput(r io.Reader) <-chan reviewtypes.Event {
	out := make(chan reviewtypes.Event, 32)
	go func() {
		defer close(out)
		out <- reviewtypes.Started{}

		scanner := bufio.NewScanner(r)
		scanner.Buffer(make([]byte, min(1024*1024, piReviewMaxScannerBuf)), piReviewMaxScannerBuf)
		messageIDsWithTextDelta := map[string]struct{}{}
		messageIDsWithUsage := map[string]struct{}{}
		messageUsageByTurn := map[int]map[piReviewUsageKey]struct{}{}
		turnNumber := 0
		tokens := reviewtypes.Tokens{}
		finished := false
		success := true

		for scanner.Scan() {
			line := scanner.Bytes()
			if len(line) == 0 {
				continue
			}
			var env piReviewEnvelope
			if err := json.Unmarshal(line, &env); err != nil {
				out <- reviewtypes.RunError{Err: fmt.Errorf("pi --mode json: %w", err)}
				continue
			}

			switch env.Type {
			case "turn_start":
				turnNumber++
			case "session", "agent_start", "queue_update", "compaction_start", "compaction_end", "auto_retry_start", "auto_retry_end":
				// Session/control events do not map to user-visible review output.
			case "message_update":
				if text := env.AssistantMessageEvent.TextDelta(); text != "" {
					messageIDsWithTextDelta[env.MessageID()] = struct{}{}
					out <- reviewtypes.AssistantText{Text: text}
				}
			case "message_end":
				if env.Message.Role == "assistant" {
					if env.Message.StopReason == "error" || env.Message.StopReason == "aborted" {
						success = false
					}
					if env.Message.Usage != nil {
						emitPiReviewTokens(out, env, &tokens, messageIDsWithUsage, messageUsageByTurn, turnNumber)
					}
					if _, sawDelta := messageIDsWithTextDelta[env.MessageID()]; !sawDelta {
						if text := piReviewMessageText(env.Message.Content); text != "" {
							out <- reviewtypes.AssistantText{Text: text}
						}
					}
				}
			case "tool_execution_start":
				out <- reviewtypes.ToolCall{Name: env.ToolName, Args: piReviewJSONArg(env.Args)}
			case "tool_execution_end":
				// Tool errors are part of normal agent execution (for example grep
				// finding no matches). The agent's stopReason determines review
				// success/failure.
			case "turn_end":
				if env.Message.StopReason == "error" || env.Message.StopReason == "aborted" {
					success = false
				}
				if env.Message.Usage != nil {
					emitPiReviewTokens(out, env, &tokens, messageIDsWithUsage, messageUsageByTurn, turnNumber)
				}
			case "agent_end":
				finished = true
				out <- reviewtypes.Finished{Success: success}
			default:
				// Unknown future events are ignored; Pi's event stream is additive.
			}
		}

		if err := scanner.Err(); err != nil {
			out <- reviewtypes.RunError{Err: fmt.Errorf("read stdout: %w", err)}
			out <- reviewtypes.Finished{Success: false}
			return
		}

func selectReviewProfile(s *settings.EntireSettings, override string) (string, settings.ReviewProfileConfig, error) {
	applyLegacyReviewProfileFallback(s)
	if s == nil || len(s.ReviewProfiles) == 0 {
		return "", settings.ReviewProfileConfig{}, errors.New("no review profiles configured; run `entire review --configure` or add review_profiles to Entire preferences")
	}
	profiles := nonZeroProfiles(s.ReviewProfiles)
	if len(profiles) == 0 {
		return "", settings.ReviewProfileConfig{}, errors.New("no review profiles configured; every profile is empty")
	}

	name := strings.TrimSpace(override)
	if name == "" {
		name = strings.TrimSpace(s.ReviewDefaultProfile)
	}
	if name == "" {
		if _, ok := profiles[DefaultProfileName]; ok {
			name = DefaultProfileName
		} else if len(profiles) == 1 {
			for only := range profiles {
				name = only
			}
		} else {
			return "", settings.ReviewProfileConfig{}, fmt.Errorf(
				"multiple review profiles configured (%s); pass a profile name or set review_default_profile",
				strings.Join(sortedMapKeys(profiles), ", "))
		}
	}

	cfg, ok := profiles[name]
	if !ok {
		return "", settings.ReviewProfileConfig{}, fmt.Errorf(
			"review profile %q is not configured; configured profiles: %s",
			name, strings.Join(sortedMapKeys(profiles), ", "))
	}
	if len(nonZeroAgentConfigs(cfg.Agents)) == 0 {
		return "", settings.ReviewProfileConfig{}, fmt.Errorf("review profile %q has no configured agents", name)
	}
	return name, cfg, nil
}

func applyLegacyReviewProfileFallback(s *settings.EntireSettings) {
	if s == nil || len(nonZeroProfiles(s.ReviewProfiles)) > 0 {
		return
	}
	legacyAgents := nonZeroAgentConfigs(s.Review) //nolint:staticcheck // intentional compatibility fallback for deprecated review config
	if len(legacyAgents) == 0 {
		return
	}
	s.ReviewProfiles = map[string]settings.ReviewProfileConfig{
		DefaultProfileName: {
			Agents: legacyAgents,
		},
	}
	if strings.TrimSpace(s.ReviewDefaultProfile) == "" {
		s.ReviewDefaultProfile = DefaultProfileName
	}
}

func selectProfileWorker(profile settings.ReviewProfileConfig, selector string) (string, settings.ReviewConfig, error) {
	selector = strings.TrimSpace(selector)
	if selector == "" {
		return "", settings.ReviewConfig{}, errors.New("empty review reviewer selector")
	}
	if cfg, ok := profile.Agents[selector]; ok && !cfg.IsZero() {
		return selector, cfg, nil
	}
	var matches []string
	for workerName, cfg := range profile.Agents {
		if cfg.IsZero() {
			continue
		}
		if reviewAgentName(workerName, cfg) == selector {
			matches = append(matches, workerName)
		}
	}
	sort.Strings(matches)
	switch len(matches) {
	case 1:
		return matches[0], profile.Agents[matches[0]], nil
	case 0:
		configured := sortedMapKeys(profile.Agents)
		if len(configured) == 0 {
			return "", settings.ReviewConfig{}, fmt.Errorf("review reviewer or agent %q is not configured", selector)
		}
		return "", settings.ReviewConfig{}, fmt.Errorf("review reviewer or agent %q is not configured; configured reviewers: %s", selector, strings.Join(configured, ", "))
	default:
		return "", settings.ReviewConfig{}, fmt.Errorf("agent %q has multiple review reviewers (%s); choose one by reviewer name", selector, strings.Join(matches, ", "))
	}
}

func workerIDForAgentModel(agentName, model string, existing map[string]settings.ReviewConfig) string {
	base := strings.TrimSpace(agentName)
	if strings.TrimSpace(model) != "" {
		base += ":" + sanitizeWorkerIDPart(model)
	}
	if base == "" {
		base = "worker"
	}
	candidate := base
	for i := 2; ; i++ {
		if _, exists := existing[candidate]; !exists {
			return candidate
		}
		candidate = fmt.Sprintf("%s-%d", base, i)
	}
}

func sanitizeWorkerIDPart(s string) string {
	s = strings.ToLower(strings.TrimSpace(s))
	var b strings.Builder
	lastDash := false
	for _, r := range s {
		keep := (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9')
		if keep {
			b.WriteRune(r)
			lastDash = false
			continue
		}
		if !lastDash {
			b.WriteByte('-')
			lastDash = true
		}
	}
	out := strings.Trim(b.String(), "-")
	if out == "" {
		return "model"
	}
	return out
}

