		}
	}
}

func TestComposeReviewPrompt_NonPositiveTimeoutNoBudgetHint(t *testing.T) {
	t.Parallel()
	// Zero (library caller didn't resolve a timeout) and negative (timeouts
	// explicitly disabled) must not render a budget — inventing a default
	// here could contradict the orchestrator's actual deadline.
	for name, timeout := range map[string]time.Duration{"zero": 0, "disabled": -1} {
