// renderTimeBudgetHint tells the agent its hard deadline so it can pace its
// review instead of running a full-depth pipeline and being killed mid-pass
// with all work discarded. Only a positive timeout renders: zero means the
// caller didn't resolve one, negative means timeouts are disabled, and
// inventing a default in either case could contradict the orchestrator's
// actual deadline.
func renderTimeBudgetHint(timeout time.Duration) string {
	if timeout <= 0 {
		return ""
	}
	deadline := timeout.String()
	if timeout%time.Minute == 0 {
		minutes := int(timeout / time.Minute)
		unit := "minutes"
		if minutes == 1 {
			unit = "minute"
		}
		deadline = fmt.Sprintf("%d %s", minutes, unit)
	}
	return "Time budget: this review is cancelled after " + deadline +
		". Pace yourself to deliver the final report comfortably within that limit — a complete report at reduced depth beats an unfinished deep pass."
}

